WITH unpacked AS (SELECT id, host, log_ts, level, latency_ms, context['region'] AS region, SIZE(context) AS num_context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, COALESCE(context['version'], 'unknown') AS version_or_default FROM app_logs WHERE level = 'DEBUG') SELECT host, DATE_TRUNC('HOUR', log_ts) AS hour_window, COUNT_IF(host = 'h2') AS h2_events, PERCENTILE_APPROX(num_context, 0.9) AS num_context_p90, MAX(log_ts) AS last_log_ts FROM unpacked GROUP BY host, hour_window ORDER BY hour_window DESC NULLS LAST;
